import AppKit
import AVFoundation
import UserNotifications
import UniformTypeIdentifiers

// Provider sign-in runs in the user's system browser. Never embed Google/OpenAI
// authentication or attempt to capture/copy the browser's authentication cookies.
final class CompanionDelegate: NSObject, NSApplicationDelegate, UNUserNotificationCenterDelegate {
    var window: NSWindow!
    var status: NSStatusItem!
    var recorder: AVAudioRecorder?
    var recordingURL: URL?
    var reminderStatus: NSTextField!
    let defaultOrigin = "https://kuwento-language-companion.copperplume66.chatgpt.site"
    var origin: URL { URL(string: UserDefaults.standard.string(forKey: "CompanionOrigin") ?? defaultOrigin)! }
    var reminder: [String:Any] { UserDefaults.standard.dictionary(forKey:"LocalReminderSchedule") ?? ["enabled":false,"paused":true,"time":"18:00","timezone":TimeZone.current.identifier] }

    func applicationDidFinishLaunching(_ notification: Notification) {
        NSApp.setActivationPolicy(.accessory)
        UNUserNotificationCenter.current().delegate = self
        window = NSWindow(contentRect:NSRect(x:0,y:0,width:650,height:620),styleMask:[.titled,.closable,.miniaturizable],backing:.buffered,defer:false)
        window.title="Kuwento · Your Mac companion";window.center();window.isReleasedWhenClosed=false
        buildWindow()
        status=NSStatusBar.system.statusItem(withLength:NSStatusItem.squareLength)
        updateMenu();buildMainMenu();scheduleReminder();showCompanion()
    }
    func text(_ string:String,size:CGFloat=14,bold:Bool=false)->NSTextField {let v=NSTextField(wrappingLabelWithString:string);v.font=bold ? .systemFont(ofSize:size,weight:.semibold):.systemFont(ofSize:size);v.textColor=NSColor(calibratedRed:0.22,green:0.32,blue:0.25,alpha:1);return v}
    func button(_ title:String,_ action:Selector)->NSButton {let b=NSButton(title:title,target:self,action:action);b.bezelStyle = .rounded;b.controlSize = .large;return b}
    func buildWindow(){
        let root=NSView();root.wantsLayer=true;root.layer?.backgroundColor=NSColor(calibratedRed:0.97,green:0.97,blue:0.94,alpha:1).cgColor;window.contentView=root
        let stack=NSStackView();stack.orientation = .vertical;stack.alignment = .leading;stack.spacing=17;stack.translatesAutoresizingMaskIntoConstraints=false;root.addSubview(stack)
        NSLayoutConstraint.activate([stack.leadingAnchor.constraint(equalTo:root.leadingAnchor,constant:38),stack.trailingAnchor.constraint(equalTo:root.trailingAnchor,constant:-38),stack.topAnchor.constraint(equalTo:root.topAnchor,constant:32)])
        let brand=text("kuwento",size:38);brand.font=NSFont(name:"Georgia",size:38);stack.addArrangedSubview(brand)
        stack.addArrangedSubview(text("YOUR LANGUAGE, LIVED · YOUR MAC COMPANION",size:10,bold:true))
        stack.addArrangedSubview(text("Your learning, one click away.",size:23,bold:true))
        stack.addArrangedSubview(text("Open the same current learner record in your system browser. ChatGPT and Google sign-in, passkeys, and Touch ID are handled by the browser and macOS.",size:14))
        let open=button("Open my learning workspace",#selector(openWorkspace));open.keyEquivalent="\r";stack.addArrangedSubview(open)
        let links=NSStackView();links.orientation = .horizontal;links.spacing=12;links.addArrangedSubview(button("Knowledge index",#selector(openKnowledge)));links.addArrangedSubview(button("Listen & speak",#selector(openAudio)));links.addArrangedSubview(button("Privacy controls",#selector(openPrivacy)));stack.addArrangedSubview(links)
        stack.addArrangedSubview(text("NATIVE TOOLS",size:10,bold:true))
        let native=NSStackView();native.orientation = .horizontal;native.spacing=12;native.addArrangedSubview(button("Record a spoken response…",#selector(toggleRecording)));native.addArrangedSubview(button("Reminder settings…",#selector(editReminder)));stack.addArrangedSubview(native)
        reminderStatus=text("",size:12);stack.addArrangedSubview(reminderStatus);updateReminderStatus()
        stack.addArrangedSubview(text("Recordings stay on this Mac until you explicitly upload them in Listen & speak. Reminder schedules are device preferences; apply your web profile’s schedule from Connect & privacy.",size:12))
        let bottom=NSStackView();bottom.orientation = .horizontal;bottom.spacing=14;bottom.addArrangedSubview(button("Continue in ChatGPT",#selector(openChatGPT)));bottom.addArrangedSubview(button("Companion server…",#selector(changeServer)));stack.addArrangedSubview(bottom)
        stack.addArrangedSubview(text("Your learning belongs to you. Open Privacy controls to manage what is saved.",size:11))
    }
    func item(_ title:String,_ action:Selector,_ key:String="")->NSMenuItem{let i=NSMenuItem(title:title,action:action,keyEquivalent:key);i.target=self;return i}
    func updateMenu(){let menu=NSMenu();menu.addItem(item("Open my learning workspace",#selector(openWorkspace),"o"));menu.addItem(item("Mac companion tools",#selector(showCompanion)));menu.addItem(item("Continue teaching in ChatGPT",#selector(openChatGPT)));menu.addItem(.separator());menu.addItem(item("Knowledge index",#selector(openKnowledge)));menu.addItem(item("Listen & speak",#selector(openAudio)));menu.addItem(item("Connect & privacy",#selector(openPrivacy)));menu.addItem(.separator());menu.addItem(item(recorder == nil ? "Record a spoken response…":"Stop & save spoken response…",#selector(toggleRecording),"r"));menu.addItem(item("Reminder settings…",#selector(editReminder)));menu.addItem(item("Pause reminders on this Mac",#selector(pauseReminders)));menu.addItem(.separator());menu.addItem(item("Companion server…",#selector(changeServer)));menu.addItem(item("Quit Kuwento",#selector(quit),"q"));status.menu=menu;status.button?.image=NSImage(systemSymbolName:recorder == nil ? "text.bubble":"mic.fill",accessibilityDescription:recorder == nil ? "Kuwento language companion":"Recording audio")}
    func buildMainMenu(){let main=NSMenu();let appItem=NSMenuItem();let appMenu=NSMenu(title:"Kuwento");appMenu.addItem(item("Open learning workspace",#selector(openWorkspace),"o"));appMenu.addItem(item("Mac companion tools",#selector(showCompanion)));appMenu.addItem(.separator());appMenu.addItem(item("Quit Kuwento",#selector(quit),"q"));appItem.submenu=appMenu;main.addItem(appItem);let editItem=NSMenuItem();let edit=NSMenu(title:"Edit");for (name,selector,key) in [("Cut","cut:","x"),("Copy","copy:","c"),("Paste","paste:","v"),("Select All","selectAll:","a")]{edit.addItem(NSMenuItem(title:name,action:Selector(selector),keyEquivalent:key))};editItem.submenu=edit;main.addItem(editItem);NSApp.mainMenu=main}
    @objc func showCompanion(){window.makeKeyAndOrderFront(nil);NSApp.activate(ignoringOtherApps:true)}
    func openView(_ view:String){var parts=URLComponents(url:origin,resolvingAgainstBaseURL:false)!;parts.fragment="view="+view;if let url=parts.url{NSWorkspace.shared.open(url)}}
    @objc func openWorkspace(){NSWorkspace.shared.open(origin)}
    @objc func openKnowledge(){openView("Knowledge index")}
    @objc func openAudio(){openView("Listen & speak")}
    @objc func openPrivacy(){openView("Connect & privacy")}
    @objc func openChatGPT(){NSWorkspace.shared.open(URL(string:"https://chatgpt.com")!)}
    @objc func quit(){recorder?.stop();if let u=recordingURL{try? FileManager.default.removeItem(at:u)};NSApp.terminate(nil)}
    func alert(_ title:String,_ message:String){let a=NSAlert();a.messageText=title;a.informativeText=message;a.addButton(withTitle:"OK");showCompanion();a.runModal()}
    @objc func changeServer(){let a=NSAlert();a.messageText="Companion server";a.informativeText="Use your hosted HTTPS origin, or localhost for development. Learner progress stays on the selected server.";a.addButton(withTitle:"Save server");a.addButton(withTitle:"Cancel");let field=NSTextField(string:origin.absoluteString);field.frame=NSRect(x:0,y:0,width:440,height:26);a.accessoryView=field;showCompanion();guard a.runModal() == .alertFirstButtonReturn else{return};guard let u=URL(string:field.stringValue),let host=u.host,(u.scheme=="https" || (u.scheme=="http" && ["localhost","127.0.0.1"].contains(host))),u.user==nil,u.password==nil else{alert("Invalid server","Use an HTTPS URL, or a local development server.");return};UserDefaults.standard.set(u.absoluteString,forKey:"CompanionOrigin")}
    func updateReminderStatus(){let r=reminder;reminderStatus?.stringValue=(r["enabled"] as? Bool==true && r["paused"] as? Bool != true) ? "Mac reminder: \(r["time"] as? String ?? "") · \(r["timezone"] as? String ?? "")":"Mac reminders are paused. Return whenever you like."}
    @objc func editReminder(){let r=reminder;let a=NSAlert();a.messageText="Optional reminder on this Mac";a.informativeText="Set a local time and IANA time zone, or apply your web profile’s schedule from Connect & privacy. Pausing has no effect on language assessments.";a.addButton(withTitle:"Enable schedule");a.addButton(withTitle:"Pause reminders");a.addButton(withTitle:"Cancel");let stack=NSStackView();stack.orientation = .vertical;stack.alignment = .leading;stack.spacing=10;let time=NSTextField(string:r["time"] as? String ?? "18:00");time.placeholderString="HH:mm";time.setAccessibilityLabel("Local reminder time, HH:mm");let zone=NSTextField(string:r["timezone"] as? String ?? TimeZone.current.identifier);zone.setAccessibilityLabel("IANA time zone");stack.addArrangedSubview(text("Local time (HH:mm)",size:12));stack.addArrangedSubview(time);stack.addArrangedSubview(text("Time zone",size:12));stack.addArrangedSubview(zone);stack.frame=NSRect(x:0,y:0,width:420,height:125);a.accessoryView=stack;showCompanion();let result=a.runModal();if result == .alertSecondButtonReturn{pauseReminders();return};guard result == .alertFirstButtonReturn else{return};applyReminder(["enabled":true,"paused":false,"time":time.stringValue,"timezone":zone.stringValue])}
    func applyReminder(_ r:[String:Any]){let time=r["time"] as? String ?? "",parts=time.split(separator:":").compactMap{Int($0)};guard parts.count==2,(0...23).contains(parts[0]),(0...59).contains(parts[1]),let zone=r["timezone"] as? String,TimeZone(identifier:zone) != nil else{alert("Check the schedule","Use a valid HH:mm time and IANA time zone, such as America/Los_Angeles.");return};UserDefaults.standard.set(r,forKey:"LocalReminderSchedule");updateReminderStatus();if r["enabled"] as? Bool==true && r["paused"] as? Bool != true{UNUserNotificationCenter.current().requestAuthorization(options:[.alert,.sound]){granted,_ in DispatchQueue.main.async{self.scheduleReminder();if !granted{self.alert("Notifications remain off","You can enable Kuwento notifications in macOS Settings. Your learning is unaffected.")}}}}else{scheduleReminder()}}
    @objc func pauseReminders(){var r=reminder;r["enabled"]=false;r["paused"]=true;UserDefaults.standard.set(r,forKey:"LocalReminderSchedule");scheduleReminder();updateReminderStatus()}
    func scheduleReminder(){let center=UNUserNotificationCenter.current();center.removePendingNotificationRequests(withIdentifiers:["kuwento-practice"]);let r=reminder;guard r["enabled"] as? Bool==true,r["paused"] as? Bool != true,let time=r["time"] as? String,let zone=r["timezone"] as? String,let tz=TimeZone(identifier:zone) else{return};let parts=time.split(separator:":").compactMap{Int($0)};guard parts.count==2 else{return};center.getNotificationSettings{settings in guard settings.authorizationStatus == .authorized else{return};var components=DateComponents();components.hour=parts[0];components.minute=parts[1];components.timeZone=tz;let content=UNMutableNotificationContent();content.title="A little Tagalog, when you’re ready";content.body="Your next conversation is waiting. A small attempt is enough.";content.sound = .default;center.add(UNNotificationRequest(identifier:"kuwento-practice",content:content,trigger:UNCalendarNotificationTrigger(dateMatching:components,repeats:true)))}}
    func application(_ application:NSApplication,open urls:[URL]){for url in urls{guard url.scheme=="kuwento",url.host=="reminders",let parts=URLComponents(url:url,resolvingAgainstBaseURL:false) else{continue};let values=Dictionary(parts.queryItems?.map{($0.name,$0.value ?? "")} ?? [],uniquingKeysWith:{first,_ in first});let a=NSAlert();a.messageText="Apply your companion reminder schedule?";a.informativeText="Time: \(values["time"] ?? "") · \(values["timezone"] ?? ""). This updates only the optional reminder on this Mac.";a.addButton(withTitle:"Apply schedule");a.addButton(withTitle:"Cancel");showCompanion();if a.runModal() == .alertFirstButtonReturn{applyReminder(["enabled":values["enabled"]=="1","paused":values["paused"]=="1","time":values["time"] ?? "","timezone":values["timezone"] ?? ""])}}}
    @objc func toggleRecording(){if let rec=recorder{rec.stop();recorder=nil;updateMenu();saveRecording();return};AVCaptureDevice.requestAccess(for:.audio){granted in DispatchQueue.main.async{guard granted else{self.alert("Microphone access is off","You can upload an existing recording or use written practice. No ability is inferred from this choice.");return};self.beginRecording()}}}
    func beginRecording(){do{let url=FileManager.default.temporaryDirectory.appendingPathComponent("kuwento-\(UUID().uuidString).m4a");let rec=try AVAudioRecorder(url:url,settings:[AVFormatIDKey:kAudioFormatMPEG4AAC,AVSampleRateKey:44100,AVNumberOfChannelsKey:1,AVEncoderAudioQualityKey:AVAudioQuality.high.rawValue]);guard rec.record() else{throw NSError(domain:"Kuwento",code:1)};recordingURL=url;recorder=rec;updateMenu();alert("Recording a spoken response","Use the menu-bar item again to stop and choose whether to save a local audio file. Nothing is uploaded or assessed automatically.")}catch{alert("Recording unavailable",error.localizedDescription)}}
    func saveRecording(){guard let u=recordingURL else{return};let panel=NSSavePanel();panel.title="Save this spoken response on your Mac";panel.nameFieldStringValue="Kuwento spoken response.m4a";panel.allowedContentTypes=[.mpeg4Audio];showCompanion();panel.beginSheetModal(for:window){response in defer{try? FileManager.default.removeItem(at:u);self.recordingURL=nil};guard response == .OK,let dest=panel.url else{return};do{if FileManager.default.fileExists(atPath:dest.path){try FileManager.default.removeItem(at:dest)};try FileManager.default.copyItem(at:u,to:dest);self.alert("Saved on this Mac","Open Listen & speak in your browser, enable recording retention, and upload this file to retain it in your shared learner record. No pronunciation score has been assigned.")}catch{self.alert("Could not save audio",error.localizedDescription)}}}
    func userNotificationCenter(_ center:UNUserNotificationCenter,didReceive response:UNNotificationResponse,withCompletionHandler completionHandler:@escaping()->Void){DispatchQueue.main.async{self.openWorkspace()};completionHandler()}
    func userNotificationCenter(_ center:UNUserNotificationCenter,willPresent notification:UNNotification,withCompletionHandler completionHandler:@escaping(UNNotificationPresentationOptions)->Void){completionHandler([.banner,.sound])}
}
let app=NSApplication.shared
let delegate=CompanionDelegate()
app.delegate=delegate
app.run()
